"""Catalogs loaded from data/*.json (generated by tools/build_data.py, then hand-editable)."""
import json
import os

DATA_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data")


DIFFICULTIES = ["VeryEasy", "Easy", "Normal", "Hard", "Impossible"]      # g_difficulty 0x00F2A988 order


class Catalog:
    """difficulty: applies data/difficulty.json (tools/build_data.py; docs/logic/difficulty.md) on top of the base
    data (Normal): building cost and risks, the house table, the tax sentiment column, start funds %."""
    def __init__(self, data_dir=DATA_DIR, difficulty="Normal"):
        def load(name):
            with open(os.path.join(data_dir, f"{name}.json")) as f:
                return json.load(f)
        self.buildings = load("buildings")          # key -> spec dict
        self.houses = load("houses")                # level 0..6 -> spec dict
        self.resources = {r["key"]: r for r in load("resources")}
        self.rules = load("rules")
        self.trade = load("trade")                  # partner cities, prices (tools/build_data.py TRADE)
        self.foods = [k for k, r in self.resources.items() if r["food"]]
        # goods of the Poseidon expansion (resources.json "poseidon"): off while `poseidon` is off (economy.good_on)
        self.poseidon_goods = {k for k, r in self.resources.items() if r.get("poseidon")}
        # deliberate fixes of exe bugs (data/fixes.json, the decision log 10-30): fixed(name)
        self.fixes = load("fixes") if os.path.exists(os.path.join(data_dir, "fixes.json")) else {}
        if difficulty not in DIFFICULTIES:
            raise ValueError(f"difficulty is one of {', '.join(DIFFICULTIES)}, not '{difficulty}'")
        self.rules["difficulty"] = difficulty
        ov = load("difficulty")[difficulty] if os.path.exists(os.path.join(data_dir, "difficulty.json")) else None
        if ov and difficulty != "Normal":
            for key, fields in ov["buildings"].items():
                if key in self.buildings:
                    self.buildings[key].update(fields)
            self.houses = ov["houses"]
            for lv, v in zip(self.rules["tax_levels"], ov["tax_sentiment"]):
                lv["sentiment"] = v
        self.rules["start_funds_pct"] = ov["start_funds_pct"] if ov else 100

    def spec(self, key):
        return self.buildings[key]

    def fixed(self, name):
        """True: ours, the exe bug `name` fixed (data/fixes.json; default); False: the exe's rule."""
        e = self.fixes.get(name)
        return True if e is None else bool(e.get("fixed", True))

    def is_food(self, good):
        return good in self.resources and self.resources[good]["food"]
